mapper.select:
SELECT a.attendance_id, e.emp_id, e.emp_code, e.emp_name, e.dept_name, a.work_date, a.clock_in_time, a.clock_out_time, a.work_status FROM t_attendance a INNER JOIN m_employee e ON a.emp_id = e.emp_id
e.delete_flg = 0
AND a.emp_id = #{empId}
AND DATE_FORMAT(a.work_date, '%Y-%m') = #{yearMonth}
ORDER BY a.work_date DESC, e.emp_id ASC

mapper.insert:
